define([],function(){const create=(root,config)=>new Promise((resolve,reject)=>{const moduleid=String(config.adaptermodule||"");if(!/^videoprogresssource_[a-z0-9_]+\/player$/.test(moduleid)){reject(new Error("Invalid Video Bridge source adapter"));return}require([moduleid],module=>{if(!module||typeof module.create!=="function"){reject(new Error("Video Bridge source adapter unavailable"));return}Promise.resolve(module.create(root,config)).then(resolve,reject)},reject)});return{create:create}});